import {STORAGE,restoreSession,saveSession,validKey} from './session.js?v=5';
import {splitAmount,expenseBalances,settlements,addExpense,removeExpense,clearSettledExpenses,removePerson,uid,iso,date,addDays,nextDue,away,assignee,advance,emptyHome,demoHome,validateHome,record,complete,rollOver,skip,schedule,calendar} from './core.js?v=5';
import {SheetsSync} from './sync.js?v=5';
import {BACKEND_URL} from './config.js?v=5';

const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',check:'<path d="m5 12 4 4 10-10"/>',tasks:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v4H9zM9 12h6M9 16h6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',settings:'<path d="m9 3 1 3h4l1-3 4 3-2 3 2 3 2 1-2 5-3-1-3 2-1 3H8l-1-3-3-2-2-3 3-2 1-3-2-3Z"/><circle cx="12" cy="12" r="3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',repeat:'<path d="M4 8h14l-3-3M20 16H6l3 3M20 8v4M4 16v-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',bell:'<path d="M5 17h14l-2-4V8a5 5 0 0 0-10 0v5Zm5 3h4"/>',leaf:'<path d="M5 18C1 6 12 3 21 3c0 12-6 17-13 14M5 21 16 9"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 10 6-4m-6 8 6 4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4M18 4h4"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l4 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',wallet:'<path d="M4 7h15a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a2 2 0 0 1 2-2h11v3"/><path d="M16 13.5h.01"/>'};
const I=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.home}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>s.trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const avatar=(p,large=false)=>`<span class="avatar c${p?.color||0}${large?' large':''}" title="${esc(p?.name||'No one')}">${esc(initials(p?.name||'?'))}</span>`;
const dateLabel=s=>date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const money=c=>new Intl.NumberFormat('en-GB',{style:'currency',currency:home.currency||'EUR'}).format(c/100);
const personName=id=>home.people.find(p=>p.id===id)?.name||'Former flatmate';
const cents=v=>Math.round(Number(String(v).replace(',','.'))*100);
const frequency=t=>t.every===1?({day:'Daily',week:'Weekly',month:'Monthly'})[t.unit]:`Every ${t.every} ${t.unit}s`;
const $=s=>document.querySelector(s);
let home,mode='welcome',key='',revision=0,myId='',backend=BACKEND_URL,client=null,view='dashboard',filter='all',search='',weekOffset=0,busy=false,syncState='Not connected',deferredInstall=null,registration=null;
let storageOK=true,refreshing=false;
try{({home,mode,key,revision,myId,backend,storageOK}=restoreSession(localStorage,BACKEND_URL));}catch{home=emptyHome('Your household');storageOK=false;}
function persist(){try{storageOK=saveSession(localStorage,{home,mode,key,revision,myId,backend});}catch{storageOK=false;}if(mode==='shared'&&validKey(key)){const current=new URLSearchParams(location.hash.slice(1)).get('home');if(!current||current===key)history.replaceState(null,'',invitation());}if(!storageOK)toast('Keep your invitation link: this browser cannot save your home reliably.',true);}
function toast(text,error=false){const el=$('#toast');el.textContent=text;el.className='toast show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),7000);}
function setBusy(b){busy=b;document.querySelectorAll('[data-mutate],dialog button[type="submit"]').forEach(el=>{if(b){if(el.dataset.wasDisabled===undefined)el.dataset.wasDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.wasDisabled!==undefined){el.disabled=el.dataset.wasDisabled==='true';delete el.dataset.wasDisabled;}});}
const heroArt=`<svg class="hero-art" viewBox="0 0 230 170" aria-hidden="true"><ellipse cx="124" cy="153" rx="85" ry="8" fill="#d5dfc2"/><path d="M54 144V66l59-46 61 46v78Z" fill="#f9fbef" stroke="#607f56" stroke-width="2"/><path d="m43 68 70-54 73 54" fill="none" stroke="#607f56" stroke-width="3" stroke-linecap="round"/><path d="M100 144v-47a15 15 0 0 1 30 0v47" fill="#dce7c9" stroke="#607f56" stroke-width="2"/><rect x="69" y="74" width="22" height="27" rx="3" fill="#edf2df" stroke="#607f56" stroke-width="2"/><path d="M80 74v27m-11-13h22" stroke="#607f56"/><rect x="143" y="74" width="20" height="27" rx="3" fill="#edf2df" stroke="#607f56" stroke-width="2"/><path d="M153 74v27m-10-13h20" stroke="#607f56"/><path d="M39 142V104m0 18c-20-12-20-24-17-27 17 0 23 17 17 27m0 10c20-14 23-26 19-31-13 1-25 17-19 31" fill="#9fb781" stroke="#607f56" stroke-width="1.7"/><path d="M26 135h26l-4 17H30Z" fill="#d4a77b" stroke="#8a7760" stroke-width="1.7"/><path d="M191 136v-31m0 14c-15-8-20-20-14-24 15 3 20 14 14 24m0 10c19-12 19-22 15-25-15 2-21 13-15 25" fill="#a3b984" stroke="#607f56" stroke-width="1.7"/><path d="M181 135h20l-3 16h-14Z" fill="#d4a77b" stroke="#8a7760" stroke-width="1.7"/><path d="m190 41 2-7 2 7 7 2-7 2-2 7-2-7-7-2ZM45 33l1.5-5 1.5 5 5 1.5-5 1.5-1.5 5-1.5-5-5-1.5Z" fill="#9db780"/><path d="m124 115-5 5-3-3" fill="none" stroke="#6e8b59" stroke-width="2" stroke-linecap="round"/></svg>`;
const navItems=[['dashboard','grid','Overview'],['tasks','tasks','All chores'],['schedule','calendar','Schedule'],['expenses','wallet','Expenses'],['people','people','Flatmates'],['settings','settings','Settings']];
const activeTasks=()=>home.tasks.filter(t=>!t.paused);
const dueTasks=()=>activeTasks().filter(t=>t.due<=iso());
const doneWeek=()=>home.history.filter(e=>e.kind==='done'&&e.at>=new Date(date(addDays(iso(),-6))).toISOString());
function taskCard(t){
  const p=assignee(t,home.people),isDue=t.due===iso(),overdue=t.due<iso();
  return `<article class="task-card" data-task="${esc(t.id)}"><div class="task-emoji">${esc(t.icon)}</div><div class="task-content"><div class="task-title-row"><h3>${esc(t.title)}</h3><span class="badge ${t.paused?'paused':overdue?'overdue':isDue?'due':''}">${t.paused?'Paused':overdue?'Overdue':isDue?'Today':dateLabel(t.due)}</span></div><div class="task-meta"><span>${esc(t.area)}</span><span>${I('clock')}${t.minutes} min</span><span>${I('repeat')}${frequency(t)}</span></div><div class="task-bottom"><div class="assigned">${avatar(p)}<span>${p?esc(p.name):'Everyone is away'}</span></div><div class="task-controls"><button class="complete" data-action="done" data-id="${esc(t.id)}" data-mutate ${t.paused||!p?'disabled':''}>${I('check')}Mark done</button><button class="more" data-action="taskMenu" data-id="${esc(t.id)}" aria-label="Options for ${esc(t.title)}">•••</button></div></div></div></article>`;
}
function empty(title,desc,button,action,emoji='🌿'){return `<div class="empty-state"><span class="emoji">${emoji}</span><h3>${title}</h3><p>${desc}</p>${button?`<button class="btn" data-action="${action}">${I('plus')}${button}</button>`:''}</div>`;}
function activityList(limit=5){return home.history.slice(0,limit).map(e=>`<div class="activity-line"><div class="activity-dot">${I(e.kind==='done'?'check':e.kind==='skip'?'repeat':e.kind==='expense'||e.kind==='settle'?'wallet':'spark')}</div><div class="activity-text">${esc(e.text)}<small>${new Date(e.at).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('')||'<p class="activity-empty">Every little effort counts.<br>Your household activity will appear here.</p>';}
function title(k,title,desc,action='',button=''){return `<div class="page-head"><div><p class="eyebrow">${k}</p><h1>${esc(title)}</h1><p class="subhead">${desc}</p></div>${action?`<button class="btn" data-action="${action}" data-mutate>${I('plus')}${button}</button>`:''}</div>`;}
function dashboard(){
  const due=dueTasks(),done=doneWeek(),mine=activeTasks().filter(t=>assignee(t,home.people)?.id===myId);
  const tasks=(filter==='mine'?mine:filter==='today'?due:activeTasks()).slice().sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5);
  const who=home.people.find(p=>p.id===myId);
  return title('A little teamwork goes a long way',who?`Hey ${who.name}, welcome home.`:'Your home, in harmony.','Less “whose turn is it?” More enjoying your space.','addTask','Add a chore')+
  `<section class="hero"><div><p class="eyebrow">GOOD HOMES ARE A TEAM EFFORT</p><h2>A little less housework.<br>A lot more home.</h2><p>${due.length?`You have ${due.length} chore${due.length===1?'':'s'} due. Small efforts, shared fairly.`:'Your next fresh start is one small chore away.'}</p></div>${heroArt}</section>`+
  `<section class="stats" aria-label="Household statistics">${[['Chores due',due.length,due.some(t=>t.due<iso())?'Includes overdue chores':'Ready for a fresh start','tasks'],['Done this week',done.length,'A little effort adds up','check'],['Active rotations',activeTasks().length,'Everyone gets a turn','repeat'],['Flatmates',home.people.length,`${home.people.filter(p=>!away(p)).length} available today`,'people']].map(([label,note,desc,icon])=>`<div class="stat"><div class="stat-top">${label}${I(icon)}</div><strong>${note.toString().padStart(2,'0')}</strong><small class="${icon==='check'?'green':''}">${desc}</small></div>`).join('')}</section>`+
  `<div class="columns"><section><div class="section-title"><h2>Your household chores</h2><button class="text-btn" data-view="tasks">View all ${I('arrow')}</button></div><div class="filters">${[['all','All chores'],['today',`Due now (${due.length})`],['mine','My chores']].map(([f,n])=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}">${n}</button>`).join('')}</div><div class="task-list">${tasks.map(taskCard).join('')||empty('A clean slate',filter==='mine'&&!myId?'Choose yourself in Settings to see your chores.':'Add your flatmates and your first chore to start sharing the work.','Add a chore','addTask')}</div><div class="section-footer">${I('leaf')}A fairer routine. A happier home.</div></section><aside class="side-panels"><section class="panel"><div class="panel-header"><h2>The home team</h2><button class="text-btn" data-action="addPerson" aria-label="Add a flatmate">${I('plus')}</button></div>${home.people.slice(0,5).map(p=>{const n=done.filter(e=>e.person===p.id).length;return `<div class="person-line">${avatar(p)}<div><b>${esc(p.name)}${p.id===myId?' <span class="badge">You</span>':''}</b><small>${away(p)?'Taking a break':`${activeTasks().filter(t=>assignee(t,home.people)?.id===p.id).length} assigned chores`}</small></div><div class="person-progress"><span>${n} done</span><div class="bar"><i style="width:${Math.min(100,n*20)}%"></i></div></div></div>`;}).join('')||'<p class="activity-empty">Your flatmates belong here.</p>'}<div class="help-note">${I('repeat')}Chores move to the next available person in the rotation. Taking a break? Set your away dates.</div></section>${(home.expenses||[]).length?`<section class="panel"><div class="panel-header"><h2>Shared money</h2>${I('wallet')}</div>${moneySummary()}<button class="text-btn" data-view="expenses">See expenses ${I('arrow')}</button></section>`:''}<section class="panel"><div class="panel-header"><h2>Little wins</h2>${I('spark')}</div>${activityList(4)}<button class="text-btn" data-view="activity">All activity ${I('arrow')}</button></section></aside></div>`;
}
function chores(){let tasks=home.tasks.filter(t=>(filter==='paused'?t.paused:!t.paused)&&(filter!=='mine'||assignee(t,home.people)?.id===myId)&&(filter!=='today'||t.due<=iso())&&(!search||(t.title+' '+t.area).toLowerCase().includes(search.toLowerCase())));return title('Make space for the good stuff','A place for every chore.','Set the routine. Share the work. Keep things moving.','addTask','Add a chore')+`<div class="section-title"><div class="filters">${[['all','Active'],['today','Due now'],['mine','My chores'],['paused','Paused']].map(([f,n])=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}">${n}</button>`).join('')}</div><input class="search" id="search" value="${esc(search)}" placeholder="Find a chore…" aria-label="Search chores"></div><div class="full-list">${tasks.sort((a,b)=>a.due.localeCompare(b.due)).map(taskCard).join('')}</div>${!tasks.length?empty('Nothing here yet','Try another filter, or add a chore to get your routine going.','Add a chore','addTask'):''}`;}
function peoplePage(){const done=doneWeek();return title('Many hands, happier home','Meet your home team.','Add flatmates, manage breaks, and keep the workload shared.','addPerson','Add a flatmate')+`<div class="person-grid">${home.people.map(p=>`<article class="panel person-card"><div class="person-card-top">${avatar(p,true)}<button class="more" data-action="editPerson" data-id="${esc(p.id)}" aria-label="Edit ${esc(p.name)}">•••</button></div><h3>${esc(p.name)} ${p.id===myId?'<span class="badge">You</span>':''}</h3><p>${p.paused?'On a break':p.awayFrom&&p.awayTo?`Away ${dateLabel(p.awayFrom)} – ${dateLabel(p.awayTo)}`:'Available for the next turn'}</p><div class="metrics"><div><b>${activeTasks().filter(t=>assignee(t,home.people)?.id===p.id).length}</b>Assigned</div><div><b>${done.filter(e=>e.person===p.id).length}</b>Done this week</div></div></article>`).join('')}</div>${!home.people.length?empty('Home is better together','Add everyone in your flat, then include them in chore rotations.','Add a flatmate','addPerson','🏡'):''}`;}
function schedulePage(){const start=addDays(iso(),weekOffset*7),events=schedule(home,Math.max(35,(weekOffset+1)*7));return title('The week, with a little breathing room','See what’s coming.','Rotations shown here follow each chore’s order and away dates.')+`<div class="week-controls"><button data-action="prevWeek" aria-label="Previous week">‹</button><b>${dateLabel(start)} – ${dateLabel(addDays(start,6))}</b><button data-action="nextWeek" aria-label="Next week">›</button><button data-action="thisWeek">Today</button><button class="text-btn" data-action="calendar">${I('download')}Calendar</button></div><div class="schedule-grid">${Array.from({length:7},(_,i)=>{const d=addDays(start,i);return `<section class="day-column ${d===iso()?'today':''}"><div class="day-heading">${date(d).toLocaleDateString('en-GB',{weekday:'short'})}<b>${date(d).getDate()}</b></div>${events.filter(e=>e.due===d).map(e=>`<div class="day-task"><div>${esc(e.icon)} ${esc(e.title)}</div><div class="mini-person">${e.person?esc(e.person.name):'Everyone away'} · ${e.minutes} min</div></div>`).join('')||'<p class="day-heading">A little breathing room</p>'}</section>`;}).join('')}</div><div class="info-box">Future turns are a preview. Finishing, passing, or reassigning a chore updates the schedule. Unfinished turns rotate at the next scheduled occurrence and appear as missed in activity.</div>`;}
function settings(){const p=home.people.find(p=>p.id===myId);return title('Make yourself at home','Your home, your way.','Manage sharing, reminders, and the details that make this place yours.')+`<div class="settings-grid"><section class="panel"><h2>Household details</h2><p>Small details. One shared place.</p><form id="home-form"><label class="field">Home name<input name="name" value="${esc(home.name)}" maxlength="80" required></label><label class="field">Currency for shared expenses<select name="currency">${CURRENCIES.map(c=>`<option ${c===(home.currency||'EUR')?'selected':''}>${c}</option>`).join('')}</select></label><button class="btn small" type="submit" data-mutate>Save home details</button></form><label class="field" style="margin-top:20px">I am<select id="my-person"><option value="">Choose yourself</option>${home.people.map(p=>`<option value="${esc(p.id)}" ${p.id===myId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><small>This choice is just for this device. It controls your chore view and reminders.</small></label></section><section class="panel"><h2>Share your home</h2><p>${mode==='shared'?'Everyone with your household invitation can view and edit the same chores. Keep this link within your flat.':'Connect your home to Google Sheets so everyone sees the same chores and updates.'}</p><div class="buttons"><button class="btn small" data-action="share">${I('share')}${mode==='shared'?'Invite flatmates':'Connect shared home'}</button><button class="btn secondary small" data-action="connect">Connection settings</button></div><p>Connection: <b>${esc(syncState)}</b></p><button class="text-btn" data-action="newHome">Create another home ${I('arrow')}</button></section><section class="panel"><h2>Phone notifications</h2><p>Get a reminder on your phone when chores are due, even when Flatflow is closed. Daily reminders arrive between 09:00 and 10:00 Berlin time.</p><p><b>${esc(pushLabel())}</b></p><div class="buttons"><button class="btn small" data-action="notifications">${I('bell')}Enable phone notifications</button><button class="btn secondary small" data-action="testPush">Send a test notification</button><button class="text-btn" data-action="disablePush">Turn off on this device</button></div><p>On iPhone (iOS 16.4+), open in Safari → Share → Add to Home Screen, then enable notifications inside the installed app. On Android, use Chrome and allow notifications.</p><button class="text-btn" data-action="calendar">Use calendar reminders instead</button></section><section class="panel"><h2>Your data stays yours</h2><p>Save a JSON backup of people, chores, and activity. Import it to restore your home. For a shared home, importing replaces the shared household after confirmation.</p><div class="buttons"><button class="btn secondary small" data-action="export">${I('download')}Export JSON</button><button class="btn secondary small" data-action="import">Import JSON</button><button class="text-btn" data-action="trimActivity">Clear older activity</button></div><p>Backups contain household data, but exclude the invitation key and connection settings.</p></section><section class="panel"><h2>Bring Flatflow along</h2><p>Install the app on your home screen. On iPhone, use Safari’s Share menu → Add to Home Screen. On Android, use Install app or Add to Home screen.</p><button class="btn secondary small" data-action="install">${I('home')}Install Flatflow</button><p>Previously loaded chores are available offline. Shared changes need an internet connection.</p></section></div>`;}
const CURRENCIES=['EUR','GBP','USD','INR','CHF','PLN','SEK','DKK','NOK','CZK','CAD','AUD'];
const EXPENSE_CATEGORIES=['Groceries','Rent','Utilities','Internet','Household supplies','Eating out','Transport','Other'];
function moneySummary(){const net=expenseBalances(home),me=home.people.find(p=>p.id===myId);if(me){const v=net[myId]||0;return `<p class="money-line ${v>0?'positive':v<0?'negative':''}">${v>0?`You get back <b>${money(v)}</b>`:v<0?`You owe <b>${money(-v)}</b>`:'You’re all square.'}</p>`;}const open=settlements(home);return `<p class="money-line">${open.length?`${open.length} payment${open.length===1?'':'s'} to settle up`:'Everyone is square.'}</p>`;}
function expensesPage(){
  const expenses=home.expenses||[],net=expenseBalances(home),plan=settlements(home),total=expenses.filter(e=>e.kind==='expense').reduce((n,e)=>n+e.amount,0);
  const ids=[...new Set([...home.people.map(p=>p.id),...Object.keys(net)])];
  const balances=ids.map(id=>{const p=home.people.find(p=>p.id===id),v=net[id]||0;return `<div class="person-line">${avatar(p||{name:personName(id)})}<div><b>${esc(personName(id))}${id===myId?' <span class="badge">You</span>':''}</b><small>${v>0?'gets back':v<0?'owes':'all square'}</small></div><span class="balance ${v>0?'positive':v<0?'negative':''}">${v?money(Math.abs(v)):'—'}</span></div>`;}).join('')||'<p class="activity-empty">Add flatmates to start sharing costs.</p>';
  const settle=plan.map(s=>`<div class="settle-line"><span><b>${esc(personName(s.from))}</b> pays <b>${esc(personName(s.to))}</b></span><span class="balance">${money(s.amount)}</span><button class="btn small secondary" data-action="settle" data-id="${esc(s.from+'|'+s.to+'|'+s.amount)}" data-mutate>Record payment</button></div>`).join('');
  const list=expenses.map(e=>{const mine=e.shares[myId]||0,settleTo=Object.keys(e.shares)[0];return `<article class="expense-line"><div class="task-emoji">${e.kind==='settle'?'🤝':'🧾'}</div><div class="expense-main"><h3>${esc(e.kind==='settle'?`${personName(e.paidBy)} paid ${personName(settleTo)}`:e.title)}</h3><small>${dateLabel(e.spentOn)}${e.category?' · '+esc(e.category):''}${e.kind==='expense'?` · paid by ${esc(personName(e.paidBy))} · split ${Object.values(e.shares).filter(v=>v>0).length} ways`:''}</small></div><div class="expense-amount"><b>${money(e.amount)}</b>${e.kind==='expense'&&myId&&(mine||e.paidBy===myId)?`<small>${e.paidBy===myId?`you lent ${money(e.amount-mine)}`:`your share ${money(mine)}`}</small>`:''}</div><button class="more" data-action="deleteExpense" data-id="${esc(e.id)}" aria-label="Remove ${esc(e.title)}">✕</button></article>`;}).join('');
  return title('Fair shares, fewer awkward chats','Split the bills, keep the peace.','Log what you paid for the flat. Flatflow works out who owes whom with as few payments as possible.','addExpense','Add an expense')+
  `<section class="stats expense-stats" aria-label="Expense summary"><div class="stat"><div class="stat-top">Shared spending${I('wallet')}</div><strong>${money(total)}</strong><small>${expenses.filter(e=>e.kind==='expense').length} expenses logged</small></div><div class="stat"><div class="stat-top">Your balance${I('people')}</div><strong>${myId?money(Math.abs(net[myId]||0)):'—'}</strong><small class="${(net[myId]||0)>0?'green':''}">${!myId?'Choose your name in Settings':(net[myId]||0)>0?'You get back':(net[myId]||0)<0?'You owe':'All square'}</small></div><div class="stat"><div class="stat-top">To settle up${I('repeat')}</div><strong>${String(plan.length).padStart(2,'0')}</strong><small>payments needed</small></div></section>`+
  `<div class="columns"><section><div class="section-title"><h2>Expenses</h2>${expenses.length&&!plan.length?`<button class="text-btn" data-action="clearExpenses" data-mutate>Clear settled expenses</button>`:''}</div><div class="expense-list">${list||empty('No shared costs yet','Add groceries, bills or anything else the flat shares. Splits can be equal, exact amounts or by shares.','Add an expense','addExpense','🧾')}</div></section><aside class="side-panels"><section class="panel"><div class="panel-header"><h2>Balances</h2>${I('wallet')}</div>${balances}</section><section class="panel"><div class="panel-header"><h2>Settle up</h2>${I('repeat')}</div>${settle||'<p class="activity-empty">Everyone is square. Nice.</p>'}<div class="help-note">${I('info')}Payments happen outside Flatflow. Record one here once the money has changed hands.</div></section></aside></div>`;
}
function expenseForm(){
  if(home.people.length<2){toast('Add at least two flatmates to share expenses.');personForm();return;}
  const paidBy=home.people.some(p=>p.id===myId)?myId:home.people[0].id;
  dialog('Share a cost.','Log what you paid. Everyone included owes their share to the person who paid.',`<div class="form-row"><label class="field">What was it?<input name="title" maxlength="100" required placeholder="e.g. Weekly groceries"></label><label class="field">Amount (${esc(home.currency||'EUR')})<input name="amount" id="expense-amount" inputmode="decimal" type="number" min="0.01" step="0.01" required placeholder="0.00"></label></div><div class="form-row three"><label class="field">Paid by<select name="paidBy">${home.people.map(p=>`<option value="${esc(p.id)}" ${p.id===paidBy?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Date<input type="date" name="spentOn" value="${iso()}" max="${iso()}" required></label><label class="field">Category<select name="category">${EXPENSE_CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></label></div><label class="field">Split<select name="mode" id="split-mode"><option value="equal">Equally</option><option value="exact">Exact amounts</option><option value="shares">By shares (e.g. 2 : 1)</option></select></label><div class="rotation-list" id="split-list">${home.people.map(p=>`<div class="rotation-item split-item"><input type="checkbox" aria-label="Include ${esc(p.name)}" data-split="${esc(p.id)}" checked>${avatar(p)}<span>${esc(p.name)}</span><input class="split-value" data-split-value="${esc(p.id)}" inputmode="decimal" type="number" min="0" step="0.01" aria-label="${esc(p.name)} amount or shares" hidden><b class="split-preview" data-preview="${esc(p.id)}"></b></div>`).join('')}</div><p class="info-box" id="split-summary"></p>`,'Add expense',async f=>{const amount=cents(f.get('amount')),shares=computeShares(amount);if(await mutate(h=>{addExpense(h,{title:f.get('title').trim(),category:f.get('category'),spentOn:f.get('spentOn'),paidBy:f.get('paidBy'),amount,shares});},'Expense added. Balances updated.'))$('#modal').close();});
  const update=()=>{const mode=$('#split-mode').value;document.querySelectorAll('[data-split-value]').forEach(el=>{el.hidden=mode==='equal';el.placeholder=mode==='shares'?'1':'0.00';el.step=mode==='shares'?'1':'0.01';});let shares={},msg='';try{shares=computeShares(cents($('#expense-amount').value||0));msg='Split looks good.';}catch(err){msg=err.message;}document.querySelectorAll('[data-preview]').forEach(el=>{el.textContent=shares[el.dataset.preview]?money(shares[el.dataset.preview]):'';});$('#split-summary').textContent=msg;};
  $('#dialog-form').addEventListener('input',update);update();
}
// Reads the split controls in the open expense dialog and returns exact cents per person.
function computeShares(amount){
  const mode=$('#split-mode').value,included=[...document.querySelectorAll('[data-split]')].filter(el=>el.checked).map(el=>el.dataset.split);
  if(!(amount>0))throw new Error('Enter an amount above zero.');
  if(!included.length)throw new Error('Choose at least one flatmate to split with.');
  const value=id=>$(`[data-split-value="${id}"]`).value;
  if(mode==='equal')return splitAmount(amount,Object.fromEntries(included.map(id=>[id,1])));
  if(mode==='shares')return splitAmount(amount,Object.fromEntries(included.map(id=>[id,Math.max(0,Number(value(id))||0)])));
  const shares=Object.fromEntries(included.map(id=>[id,Math.max(0,cents(value(id)||0))]).filter(([,v])=>v>0)),sum=Object.values(shares).reduce((n,v)=>n+v,0);
  if(sum!==amount)throw new Error(`Exact amounts add up to ${money(sum)}. ${sum<amount?money(amount-sum)+' left to assign.':money(sum-amount)+' too much.'}`);
  return shares;
}
function render(){
  if(mode==='welcome'){
    $('#app').innerHTML=`<main class="main"><div class="brand">${I('home')}flatflow.</div>${title('Welcome home','Your flat. Your shared routine.','Already invited? Open your household invitation or paste it below.')}<section class="panel"><h2>Join your flatmates</h2><p>Your real household lives in Google Sheets. Opening a different browser or clearing browser data may require your invitation again.</p><button class="btn" data-action="joinLink">Paste invitation link</button><button class="btn secondary" data-action="newHome">Create a new household</button></section></main>`;return;
  }
  const who=home.people.find(p=>p.id===myId),page={dashboard,tasks:chores,people:peoplePage,schedule:schedulePage,expenses:expensesPage,settings,activity:()=>title('Every small effort matters','Your household’s little wins.','Completed chores, passed turns, and changes to your routine.')+`<section class="panel">${activityList(200)}</section>`}[view]||dashboard;
  const statusClass=mode!=='shared'||syncState!=='Synced with Google Sheets'?'warn':'';
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${I('home')}flatflow<span style="color:#92a577">.</span></div><div class="home-pill"><span class="home-icon">⌂</span><div><b>${esc(home.name)}</b><small>${home.people.length} flatmates · one home</small></div></div><nav class="nav" aria-label="Main navigation">${navItems.map(([v,i,n])=>`<button data-view="${v}" class="${view===v?'active':''}">${I(i)}${n}${v==='tasks'?`<span class="count">${activeTasks().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="install-card">${I('leaf')}<p><strong>A happier home, in your pocket.</strong></p><p>Your little routine, wherever you are.</p><button data-action="install">Install the app ↗</button></div><p class="small-brand">Made for the place you call home.</p></div></aside><main class="main" id="main" tabindex="-1"><header class="topbar"><div class="breadcrumb">Your household <b>/ ${navItems.find(i=>i[0]===view)?.[2]||'Activity'}</b></div><div class="mobile-home-name">${I('home')}flatflow.</div><div class="top-actions"><span class="today-label">${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}</span><span class="sync-tag ${statusClass}" title="${esc(syncState)}"><span class="sync-dot"></span>${mode==='shared'?syncState==='Synced with Google Sheets'?'Shared · synced':esc(syncState):mode==='demo'?'Demo home':'Saved on this device'}</span><button data-action="notifications" aria-label="Reminder settings">${I('bell')}</button><button data-action="chooseMe" aria-label="${who?'You are '+esc(who.name)+'. Change your name':'Choose your name'}" title="Choose your name">${avatar(who)}</button></div></header>${mode==='demo'?`<div class="notice" style="margin-top:22px">You’re exploring a sample home. Make a fresh start with your own flatmates.<button class="text-btn" data-action="newHome">Create your home ${I('arrow')}</button></div>`:''}${mode==='shared'&&syncState!=='Synced with Google Sheets'?`<div class="notice" style="margin-top:20px">${esc(syncState)}. Showing the last saved household. Reconnect before editing.<button class="text-btn" data-action="reconnect">Reconnect ${I('repeat')}</button></div>`:''}${mode==='shared'&&home.people.length&&!who&&view!=='settings'?`<div class="notice" style="margin-top:20px">Who’s using this device? Choose your name to see your chores and enable personal reminders.<button class="text-btn" data-action="chooseMe">Choose your name ${I('people')}</button></div>`:''}${!storageOK?'<div class="notice">Keep your invitation link. This browser cannot reliably remember your home.</div>':''}${page()}<footer class="app-footer"><span>flatflow. &nbsp; A little routine, a lot more home.</span><span>${mode==='shared'?'Shared through Google Sheets':'Your data is saved on this device'}</span></footer></main><nav class="mobile-nav" aria-label="Mobile navigation">${navItems.map(([v,i,n])=>`<button data-view="${v}" class="${view===v?'active':''}">${I(i)}${n==='Overview'?'Home':n==='All chores'?'Chores':n==='Expenses'?'Money':n}</button>`).join('')}</nav></div>`;
  setBusy(busy);
  $('#my-person')?.addEventListener('change',async e=>{const next=e.target.value;try{if(localStorage.getItem('flatflow-push'))await disablePush();myId=next;persist();render();}catch(err){toast(err.message,true);render();}});
  $('#search')?.addEventListener('input',e=>{const position=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(position,position);});
  $('#home-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);await mutate(h=>{h.name=f.get('name').trim();h.currency=f.get('currency');},'Home details saved');});
}
function dialog(title,description,body,submitLabel,onSubmit){
  const el=$('#modal');if(el.open)el.close();el.innerHTML=`<div class="dialog-top"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">${I('close')}</button></div><p class="dialog-description">${description}</p><form id="dialog-form">${body}${submitLabel?`<div class="dialog-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn" data-mutate>${submitLabel}</button></div>`:''}</form>`;el.showModal();
  $('#dialog-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;try{await onSubmit(new FormData(e.target),e.target);}catch(err){toast(err.message,true);}});
}
async function connectClient(){if(!backend)throw new Error('Connect the Google Sheets backend in Settings first.');if(client?.url===backend){await client.ready;return;}client?.close();client=new SheetsSync(backend);await client.ready;}
async function refresh(force=false){if(mode!=='shared'||busy||refreshing||(!force&&document.visibilityState==='hidden'))return;refreshing=true;const requestedKey=key,requestedRevision=revision;try{if(!client)await connectClient();const r=await client.call({action:'read',key,revision:force?-1:revision});if(key!==requestedKey||busy||revision!==requestedRevision)return;if(r.home){home=validateHome(r.home);revision=r.revision;if(!home.people.some(p=>p.id===myId))myId='';persist();}const changed=syncState!=='Synced with Google Sheets'||!!r.home;syncState='Synced with Google Sheets';if(changed)render();notifyDue();}catch(err){syncState=navigator.onLine?'Connection needs attention':'Offline';client?.close();client=null;render();}finally{refreshing=false;}}
async function mutate(fn,message='Changes saved'){
  if(busy)return false;if(mode==='shared'&&syncState!=='Synced with Google Sheets'){toast('Reconnect to your household before editing.',true);return false;}setBusy(true);const draft=structuredClone(home);
  try{rollOver(draft);fn(draft);validateHome(draft);if(mode==='shared'){
    if(!navigator.onLine)throw new Error('You’re offline. Reconnect to save a shared change.');
    if(!client)await connectClient();syncState='Saving…';
    const result=await client.call({action:'write',key,revision,op:uid(),home:draft});
    if(result.conflict){try{localStorage.setItem('flatflow-conflict-draft',JSON.stringify(draft));}catch{}home=validateHome(result.home);revision=result.revision;persist();syncState='Synced with Google Sheets';render();dialog('A flatmate got there first.','Your change hasn’t overwritten theirs. The latest household is now loaded. You can save your attempted change as a backup and try again.','<div class="info-box">Reopen the chore or flatmate to apply your change to the latest version.</div><button type="button" class="btn secondary" data-action="exportDraft">Download my attempted change</button>','Got it',async()=>$('#modal').close());return false;}
    home=validateHome(result.home);revision=result.revision;syncState='Synced with Google Sheets';
  }else home=draft;persist();render();toast(message);return true;
  }catch(err){syncState=mode==='shared'?'Connection needs attention':syncState;toast(err.message,true);return false;}finally{setBusy(false);if(mode==='shared')render();}
}
function personForm(id=''){
  const p=home.people.find(p=>p.id===id)||{name:'',color:home.people.length%6,paused:false,awayFrom:'',awayTo:''};
  dialog(id?'Edit your flatmate':'A new face at home',id?'Set a break or away dates. New assignments skip unavailable people.':'Add everyone who shares the work. You can choose who joins each rotation.',`<label class="field">Name<input name="name" value="${esc(p.name)}" maxlength="60" required placeholder="e.g. Alex"></label><label class="field">Avatar colour<select name="color">${['Sage','Peach','Blue','Lilac','Mint','Yellow'].map((c,i)=>`<option value="${i}" ${p.color===i?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-row"><label class="field">Away from<input type="date" name="awayFrom" value="${esc(p.awayFrom)}"></label><label class="field">Away until<input type="date" name="awayTo" value="${esc(p.awayTo)}"></label></div><label class="check-row"><input type="checkbox" name="paused" ${p.paused?'checked':''}>Take a break from all rotations</label>${id?`<button type="button" class="btn danger" data-action="deletePerson" data-id="${esc(id)}">Delete flatmate</button><p>Past activity stays in your household history.</p>`:''}`,'Save flatmate',async f=>{const from=f.get('awayFrom'),to=f.get('awayTo');if(!!from!==!!to||from&&to<from)throw new Error('Enter both away dates, with the end on or after the start.');const success=await mutate(h=>{const target=h.people.find(x=>x.id===id),values={name:f.get('name').trim(),color:Number(f.get('color')),paused:f.has('paused'),awayFrom:from,awayTo:to};if(target)Object.assign(target,values);else{if(h.people.length>=30)throw new Error('This home supports up to 30 flatmates.');h.people.push({id:uid(),...values});}record(h,'person',`${values.name} ${id?'updated their availability':'joined the home'}`);},id?'Flatmate updated':'Welcome to the home team');if(success){if(!myId&&home.people.length===1){myId=home.people[0].id;persist();render();}$('#modal').close();}});
}
function taskForm(id=''){
  if(!home.people.length){toast('Add your flatmates first, then start a chore rotation.');personForm();return;}
  const t=home.tasks.find(t=>t.id===id)||{title:'',area:'Kitchen',icon:'🧹',minutes:15,every:1,unit:'week',due:iso(),notes:'',order:home.people.map(p=>p.id),turn:0,paused:false};
  let order=[...t.order,...home.people.filter(p=>!t.order.includes(p.id)).map(p=>p.id)];let selected=new Set(t.order);
  dialog(id?'Fine-tune the routine':'A small chore. A shared effort.','Set a schedule and a rotation order. Completing a chore advances its due date and gives the next person a turn.',`<label class="field">Chore name<input name="title" value="${esc(t.title)}" maxlength="100" placeholder="e.g. Bathroom sparkle" required></label><div class="form-row"><label class="field">Space<select name="area">${['Kitchen','Bathroom','Living room','Whole home','Outdoors','Other'].map(a=>`<option ${t.area===a?'selected':''}>${a}</option>`).join('')}</select></label><label class="field">Icon<select name="icon">${['🧹','🍳','🫧','♻️','🌿','🧊','🧺','🗑️','🛒','✨','🪴','🛁'].map(a=>`<option ${t.icon===a?'selected':''}>${a}</option>`).join('')}</select></label></div><div class="form-row three"><label class="field">Repeat every<input type="number" min="1" max="365" name="every" value="${t.every}" required></label><label class="field">Period<select name="unit">${[['day','Day(s)'],['week','Week(s)'],['month','Month(s)']].map(([v,n])=>`<option value="${v}" ${t.unit===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Minutes<input type="number" min="1" max="600" name="minutes" value="${t.minutes}" required></label></div><label class="field">Next due date<input type="date" name="due" value="${esc(t.due)}" required><small>Monthly chores keep this day of the month, using the last day in shorter months.</small></label><label class="field">Rotation order<small>Choose participants. Use the arrows to set the order.</small></label><div class="rotation-list" id="rotation-list"></div><label class="field">First / current turn<select name="assigned" id="assigned-select"></select></label><label class="field">A helpful note<textarea name="notes" maxlength="1000" placeholder="What does a job well done look like?">${esc(t.notes)}</textarea></label><label class="check-row"><input type="checkbox" name="paused" ${t.paused?'checked':''}>Pause this chore</label>`,'Save chore',async(f,form)=>{const chosen=order.filter(id=>selected.has(id));if(!chosen.length)throw new Error('Choose at least one flatmate for the rotation.');const success=await mutate(h=>{const values={title:f.get('title').trim(),area:f.get('area'),icon:f.get('icon'),minutes:Number(f.get('minutes')),every:Number(f.get('every')),unit:f.get('unit'),due:f.get('due'),anchorDay:t.due===f.get('due')&&id?t.anchorDay:date(f.get('due')).getDate(),notes:f.get('notes').trim(),order:chosen,turn:Math.max(0,chosen.indexOf(f.get('assigned'))),paused:f.has('paused')};const old=h.tasks.find(t=>t.id===id);if(old)Object.assign(old,values);else{if(h.tasks.length>=100)throw new Error('This home supports up to 100 chores.');h.tasks.push({id:uid(),...values});}record(h,'task',`${values.title} ${id?'was updated':'joined the routine'}`);},id?'Routine updated':'Your new chore is in the rotation');if(success)$('#modal').close();});
  const fillOrder=()=>{const assigned=$('#assigned-select').value||t.order[t.turn];$('#rotation-list').innerHTML=order.map((id,i)=>{const p=home.people.find(p=>p.id===id);return `<div class="rotation-item"><input type="checkbox" aria-label="Include ${esc(p.name)}" data-rotation="${esc(id)}" ${selected.has(id)?'checked':''}>${avatar(p)}${esc(p.name)}<div class="reorder"><button type="button" data-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Move ${esc(p.name)} up">↑</button><button type="button" data-move="${i}" data-dir="1" ${i===order.length-1?'disabled':''} aria-label="Move ${esc(p.name)} down">↓</button></div></div>`;}).join('');$('#assigned-select').innerHTML=order.filter(id=>selected.has(id)).map(id=>{const p=home.people.find(p=>p.id===id);return `<option value="${esc(id)}" ${assigned===id?'selected':''}>${esc(p.name)}</option>`;}).join('');};fillOrder();$('#rotation-list').addEventListener('change',e=>{if(e.target.dataset.rotation){e.target.checked?selected.add(e.target.dataset.rotation):selected.delete(e.target.dataset.rotation);fillOrder();}});$('#rotation-list').addEventListener('click',e=>{const b=e.target.closest('[data-move]');if(b){const i=Number(b.dataset.move),j=i+Number(b.dataset.dir);[order[i],order[j]]=[order[j],order[i]];fillOrder();}});
}
function taskMenu(id){const t=home.tasks.find(t=>t.id===id);if(!t)return;dialog(esc(t.title),`${esc(t.notes)||'Everyone gets a turn. Let’s keep it fair.'}<br>Next due: ${dateLabel(t.due)} · ${frequency(t)}`,`<div class="menu-actions"><button type="button" class="btn secondary" data-action="editTask" data-id="${esc(id)}">Edit schedule & rotation</button><button type="button" class="btn secondary" data-action="skip" data-id="${esc(id)}">Pass this turn to the next flatmate</button><button type="button" class="btn secondary" data-action="snooze" data-id="${esc(id)}">Postpone this chore</button><button type="button" class="btn secondary" data-action="reassign" data-id="${esc(id)}">Give this turn to someone else</button><button type="button" class="btn secondary" data-action="pauseTask" data-id="${esc(id)}">${t.paused?'Resume':'Pause'} this chore</button><button type="button" class="btn danger" data-action="deleteTask" data-id="${esc(id)}">Remove this chore</button></div>`);}
function keygen(){return Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');}
function newHome(){dialog('Make this place yours.','Start fresh with your flatmates. Your current home stays available through its saved invitation.',`<label class="field">Home name<input name="name" maxlength="80" placeholder="e.g. The Berlin flat" required></label><label class="field">Save mode<select name="mode"><option value="shared">Shared home · sync with Google Sheets</option><option value="local">Personal home · this device only</option></select></label><p class="info-box">Shared homes use an invitation link. Anyone with that link can manage the household. Keep a copy so you can reopen it on another phone.</p>${!backend?'<label class="field">Google Apps Script deployment URL<input type="url" name="backend" placeholder="https://script.google.com/macros/s/…/exec"><small>The app owner connects this once after deploying the included backend.</small></label>':''}`,'Create my home',async f=>{const draft=emptyHome(f.get('name').trim());validateHome(draft);if(f.get('mode')==='shared'){backend=BACKEND_URL||f.get('backend')||backend;setBusy(true);try{await connectClient();const newKey=keygen(),r=await client.call({action:'create',key:newKey,op:uid(),home:draft});home=validateHome(r.home);key=newKey;revision=r.revision;mode='shared';syncState='Synced with Google Sheets';}finally{setBusy(false);}}else{home=draft;mode='local';key='';revision=0;syncState='Saved on this device';client?.close();client=null;}myId='';view='people';history.replaceState(null,'',location.pathname);persist();$('#modal').close();render();toast('Welcome home. Let’s add your flatmates.');});}
function connectionDialog(){dialog('Connect your household.','Google Sheets keeps your home in sync. The spreadsheet itself stays private.',`<label class="field">Apps Script web app URL<input name="backend" type="url" value="${esc(backend)}" placeholder="https://script.google.com/macros/s/…/exec" required></label><label class="field">Household invitation link or key<input name="key" value="${esc(key)}" placeholder="Paste the invitation from your flatmate"><small>Leave blank to make this device’s current home shared.</small></label><div class="info-box">Changes sync when you’re online. Household updates are checked every 30 seconds while the app is open.</div>`,'Connect home',async f=>{const input=String(f.get('key')).trim();let newKey=input;if(input.includes('#'))newKey=new URLSearchParams(input.split('#')[1]).get('home');if(newKey&&!/^[a-f0-9]{64}$/.test(newKey))throw new Error('That invitation key is invalid. Paste the full invitation link.');backend=BACKEND_URL||String(f.get('backend')).trim();setBusy(true);try{await connectClient();if(!newKey)newKey=keygen();const r=await client.call(input?{action:'read',key:newKey,revision:-1}:{action:'create',key:newKey,home,op:uid()});home=validateHome(r.home);mode='shared';key=newKey;myId='';history.replaceState(null,'',location.pathname);revision=r.revision;syncState='Synced with Google Sheets';persist();$('#modal').close();render();toast('Connected. Your home is now shared.');}finally{setBusy(false);}});}
function invitation(){const params=new URLSearchParams({home:key});if(!BACKEND_URL)params.set('backend',backend);return `${location.origin}${location.pathname}#${params}`;}
function shareHome(){if(mode!=='shared'){connectionDialog();return;}const link=invitation();dialog('Good homes are better together.','Send this link to your flatmates. It gives them access to view and edit the shared household.',`<label class="field">Household invitation<input value="${esc(link)}" readonly id="invite-url"><small>Keep this link within your household. Store a copy to recover your home on another device.</small></label><div class="buttons"><button class="btn" type="button" data-action="copyInvite">Copy invitation</button>${navigator.share?'<button class="btn secondary" type="button" data-action="nativeShare">Share…</button>':''}</div>`);}
function download(content,filename,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportHome(){download(JSON.stringify(home,null,2),'flatflow-backup-'+iso()+'.json');toast('Your household backup is ready.');}
async function importHome(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.className='file-input';document.body.append(input);input.addEventListener('change',async()=>{try{const file=input.files[0];if(!file)return;if(file.size>80000)throw new Error('That backup is too large.');const imported=validateHome(JSON.parse(await file.text()));dialog('Restore this household?',`This will replace ${esc(home.name)} with ${esc(imported.name)}, including ${imported.people.length} flatmates and ${imported.tasks.length} chores. ${mode==='shared'?'All connected flatmates will see the change.':''}`,'<p class="info-box">Export your current home first if you’d like to keep a copy.</p><button class="btn secondary small" type="button" data-action="export">Export current home</button>','Restore backup',async()=>{const success=await mutate(h=>{for(const k of Object.keys(h))delete h[k];Object.assign(h,imported);},'Household restored');if(success)$('#modal').close();});}catch(err){toast(err.message,true);}finally{input.remove();}},{once:true});input.click();}
function calendarDialog(){dialog('A little nudge from your calendar.','Export the next 60 days of chore assignments, with a reminder at 09:00 on each due date.',`<label class="field">Whose chores?<select name="person"><option value="">Everyone</option>${home.people.map(p=>`<option value="${esc(p.id)}" ${myId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><p class="info-box">Open the downloaded .ics file in Apple Calendar, Google Calendar, or your calendar app. It’s a snapshot, so export it again after changing your routine. Calendar apps control whether alarms are imported.</p>`,'Download calendar',async f=>{download(calendar(home,f.get('person')),'flatflow-chores.ics','text/calendar');$('#modal').close();toast('Your calendar is ready to import.');});}
function pushLabel(){try{const saved=JSON.parse(localStorage.getItem('flatflow-push')||'null');if(saved&&saved.home===home.id&&saved.person===myId&&'Notification'in window&&Notification.permission==='granted')return 'Enabled for '+(home.people.find(p=>p.id===myId)?.name||'you')+' on this device';}catch{}return 'Not enabled for your selected name on this device';}
async function notifications(){
  if(mode!=='shared'){toast('Connect a shared home first.');return;}
  if(!myId){view='settings';render();toast('Choose your name in Settings → I am first.');return;}
  if(!('Notification'in window)||!('PushManager'in window)){await install();toast('Open the installed app to enable phone notifications.',true);return;}
  const permission=await Notification.requestPermission();
  if(permission!=='granted'){toast('Allow notifications in your browser or phone settings, then try again.',true);return;}
  setBusy(true);try{
    await connectClient();const config=await client.call({action:'pushConfig',key});
    if(!config.enabled||!config.publicKey)throw new Error('The phone reminder service is not ready yet.');
    const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();
    if(!sub){const raw=atob(config.publicKey.replace(/-/g,'+').replace(/_/g,'/'));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(raw,c=>c.charCodeAt(0))});}
    await client.call({action:'subscribePush',key,person:myId,endpoint:sub.endpoint});
    localStorage.setItem('flatflow-push',JSON.stringify({home:home.id,person:myId}));render();toast('Phone notifications enabled. You can send a test below.');
  }finally{setBusy(false);}
}
async function testPush(){if(mode!=='shared'||!myId||!('serviceWorker'in navigator)||!('PushManager'in window))throw new Error('Choose your name and enable phone notifications first.');const sub=await (await navigator.serviceWorker.ready).pushManager.getSubscription();if(!sub)throw new Error('Enable phone notifications first.');await connectClient();await client.call({action:'testPush',key,endpoint:sub.endpoint});toast('Test sent. Check your phone’s notifications.');}
async function disablePush(){if(!('serviceWorker'in navigator))return;const sub=await (await navigator.serviceWorker.ready).pushManager.getSubscription();if(sub){await connectClient();await client.call({action:'unsubscribePush',key,endpoint:sub.endpoint});await sub.unsubscribe();}localStorage.removeItem('flatflow-push');render();toast('Phone notifications turned off on this device.');}
async function notifyDue(){} // Background delivery is handled by the push service.
async function install(){if(deferredInstall){await deferredInstall.prompt();const r=await deferredInstall.userChoice;if(r.outcome==='accepted')toast('Flatflow is ready for your home screen.');deferredInstall=null;}else dialog('A happier home, in your pocket.','Flatflow works as an app on your phone.','<div class="info-box"><b>iPhone / iPad</b><br>Open this page in Safari. Tap Share, then Add to Home Screen.<br><br><b>Android</b><br>Open this page in Chrome. Tap the menu, then Install app or Add to Home screen.<br><br><b>Desktop</b><br>Use your browser’s Install button or menu when available.</div>','Got it',async()=>$('#modal').close());}
function joinLink(){dialog('Open your household','Paste the invitation your flatmate sent you.', '<label class="field">Invitation link<input name="invite" type="text" required placeholder="https://…/#home=…"></label>', 'Open household',async f=>{const value=String(f.get('invite')).trim();const k=validKey(value)?value:new URLSearchParams(value.split('#')[1]||'').get('home');if(!validKey(k))throw new Error('Paste a complete Flatflow invitation link.');location.hash=new URLSearchParams({home:k}).toString();await handleInvitation();});}
async function handleInvitation(){
 const params=new URLSearchParams(location.hash.slice(1));if(!params.has('home'))return;
 const invitedKey=params.get('home');if(!validKey(invitedKey)){toast('This invitation is invalid. Ask your flatmate for a new link.',true);return;}
 if(mode==='shared'&&key===invitedKey){if(syncState!=='Synced with Google Sheets'){syncState='Connecting…';render();}await refresh(true);return;}
 dialog('Your flatmates saved you a place.','Join the shared household to see the same chores and updates.', '<p class="info-box">Choose your name after joining. Keep this invitation to reopen your home in another browser or installed app.</p>', 'Join this home',async()=>{
 setBusy(true);try{await connectClient();const r=await client.call({action:'read',key:invitedKey,revision:-1});const joined=validateHome(r.home);home=joined;key=invitedKey;revision=r.revision;mode='shared';myId='';syncState='Synced with Google Sheets';persist();$('#modal').close();view='settings';render();toast('You’re home. Choose your name.');}finally{setBusy(false);}});
}
const actions={joinLink,

  chooseMe:()=>{view='settings';render();$('#my-person')?.focus();},
  deletePerson:id=>{const p=home.people.find(p=>p.id===id);if(!p)return;dialog('Delete '+esc(p.name)+'?', 'They will be removed from the household and chore rotations. Past activity stays. Export a backup first if you want to restore them later.', '<button class="btn secondary small" type="button" data-action="export">Export backup</button>', 'Delete flatmate', async()=>{if(await mutate(h=>removePerson(h,id),'Flatmate deleted')){if(myId===id){myId='';persist();}$('#modal').close();render();}});},
  close:()=>$('#modal').close(),addPerson:()=>personForm(),editPerson:id=>personForm(id),addTask:()=>taskForm(),editTask:id=>taskForm(id),taskMenu,share:shareHome,newHome,connect:connectionDialog,reconnect:async()=>{try{await connectClient();await refresh(true);}catch(err){toast(err.message,true);}},
  addExpense:()=>expenseForm(),
  settle:arg=>{const [from,to,amount]=String(arg).split('|');dialog('Record a payment.',`${esc(personName(from))} pays ${esc(personName(to))}. Record it once the money has changed hands.`,`<label class="field">Amount (${esc(home.currency||'EUR')})<input name="amount" type="number" min="0.01" step="0.01" value="${(Number(amount)/100).toFixed(2)}" required></label>`,'Record payment',async f=>{const value=cents(f.get('amount'));if(!(value>0))throw new Error('Enter an amount above zero.');if(await mutate(h=>{addExpense(h,{kind:'settle',title:'Settle up',spentOn:iso(),paidBy:from,amount:value,shares:{[to]:value}});},'Payment recorded. Balances updated.'))$('#modal').close();});},
  deleteExpense:id=>{const e=(home.expenses||[]).find(e=>e.id===id);if(!e)return;dialog('Remove this expense?',`${esc(e.kind==='settle'?'This payment':e.title)} (${money(e.amount)}) will be removed and balances recalculated.`,'','Remove expense',async()=>{if(await mutate(h=>removeExpense(h,id),'Expense removed'))$('#modal').close();});},
  clearExpenses:()=>dialog('Clear settled expenses?','Everyone is square, so the expense list can be cleared to keep your home light. Export a backup first to keep a record.','<button type="button" class="btn secondary small" data-action="export">Export backup first</button>','Clear expenses',async()=>{if(await mutate(h=>clearSettledExpenses(h),'Settled expenses cleared'))$('#modal').close();}),
  done:async id=>{await mutate(h=>complete(h,id),'One small win for your home. Next turn assigned.');},
  skip:id=>{const t=home.tasks.find(t=>t.id===id);dialog('Pass this turn.','This keeps the due date and hands the chore to the next available person.',`<label class="field">Reason (optional)<input name="reason" maxlength="200" placeholder="e.g. Away this weekend"></label>`,'Pass to next flatmate',async f=>{if(await mutate(h=>skip(h,id,f.get('reason')),'Turn passed. The due date stays the same.'))$('#modal').close();});},
  snooze:id=>{const t=home.tasks.find(t=>t.id===id);dialog('Give it a little more time.','Postpone this occurrence. The same person keeps the turn.',`<label class="field">New due date<input name="due" type="date" value="${addDays(t.due<iso()?iso():t.due,1)}" min="${iso()}" required></label>`,'Postpone chore',async f=>{if(await mutate(h=>{const target=h.tasks.find(t=>t.id===id);target.due=f.get('due');target.anchorDay=date(target.due).getDate();record(h,'snooze',`${target.title} moved to ${dateLabel(target.due)}`);},'Chore postponed'))$('#modal').close();});},
  reassign:id=>{const t=home.tasks.find(t=>t.id===id);dialog('A helping hand.','Choose who takes this occurrence. After they finish, the rotation continues from their place.',`<label class="field">Assign this turn to<select name="person">${t.order.map(id=>home.people.find(p=>p.id===id)).filter(p=>p&&!away(p,t.due)).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label>`,'Reassign turn',async f=>{if(await mutate(h=>{const target=h.tasks.find(t=>t.id===id);const i=target.order.indexOf(f.get('person'));if(i<0)throw new Error('Choose an available person in this rotation.');target.turn=i;record(h,'assign',`${target.title} assigned to ${h.people.find(p=>p.id===f.get('person')).name}`);},'Turn reassigned'))$('#modal').close();});},
  pauseTask:async id=>{if(await mutate(h=>{const t=h.tasks.find(t=>t.id===id);t.paused=!t.paused;record(h,'task',`${t.title} ${t.paused?'paused':'resumed'}`);},'Routine updated'))$('#modal').close();},
  deleteTask:id=>{const t=home.tasks.find(t=>t.id===id);dialog('Remove this chore?',`${esc(t.title)} will leave the routine. Its past activity remains. Export a backup first if you want to restore it later.`,'','Remove chore',async()=>{if(await mutate(h=>{h.tasks=h.tasks.filter(t=>t.id!==id);record(h,'task',`${t.title} removed from the routine`);},'Chore removed'))$('#modal').close();});},
  copyInvite:async()=>{try{await navigator.clipboard.writeText(invitation());toast('Invitation copied. Send it to your flatmates.');}catch{$('#invite-url').select();toast('Select and copy the invitation link.');}},
  nativeShare:async()=>{try{await navigator.share({title:'Join our Flatflow home',text:'Let’s share the work.',url:invitation()});}catch(err){if(err.name!=='AbortError')toast('Copy the invitation instead.');}},
  trimActivity:()=>dialog('Keep the recent wins.', 'This keeps the latest 30 activity entries and removes older ones. Export your JSON backup first to keep the full history.', '<button type="button" class="btn secondary small" data-action="export">Export backup first</button>', 'Keep recent activity', async()=>{if(await mutate(h=>{h.history=h.history.slice(0,30);},'Older activity cleared'))$('#modal').close();}),
  export:exportHome,import:importHome,exportDraft:()=>{const d=localStorage.getItem('flatflow-conflict-draft');if(d)download(d,'flatflow-attempted-change.json');},calendar:calendarDialog,notifications,install,testPush,disablePush,
  prevWeek:()=>{weekOffset=Math.max(0,weekOffset-1);render();},nextWeek:()=>{weekOffset=Math.min(12,weekOffset+1);render();},thisWeek:()=>{weekOffset=0;render();}
};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-view],[data-filter]');if(!b||b.disabled)return;if(b.dataset.view){view=b.dataset.view;filter='all';search='';render();window.scrollTo({top:0,behavior:'instant'});return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}try{await actions[b.dataset.action]?.(b.dataset.id);}catch(err){toast(err.message,true);}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});
window.addEventListener('online',()=>refresh(true));window.addEventListener('offline',()=>{if(mode==='shared'){syncState='Offline';render();}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh(true);});
window.addEventListener('storage',e=>{if(e.key===STORAGE&&!busy){try{const saved=JSON.parse(e.newValue);if(saved&&saved.home.id===home.id&&saved.key===key&&saved.revision>=revision){home=validateHome(saved.home);revision=saved.revision;myId=saved.myId||'';render();}}catch{}}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(r=>{registration=r;notifyDue();}).catch(()=>{});
if(mode!=='shared')rollOver(home);render();persist();
if(new URLSearchParams(location.hash.slice(1)).has('home'))handleInvitation();
else if(mode==='shared'){syncState='Connecting…';render();refresh(true);}
window.addEventListener('hashchange',()=>handleInvitation());
setInterval(()=>{refresh();if(mode!=='shared'){if(rollOver(home)){persist();render();}notifyDue();}},30000);
